% ------------------------------------------------------------------- ROI

nx = 15;    % Кол-во точек вдоль Х
ny = 15;    % Кол-во точек вдоль Y
nz = 15;    % Кол-во точек вдоль Z
K = nx*ny*nz;  % Полное число точек ROI

lx = 30/1000;  % Длина области вдоль Х
ly = 30/1000;  % Длина области вдоль Y
lz = 30/1000;  % Длина области вдоль Z

CenterROI = [0 0 0]; % Положение центра ROI

ROI = CreateCubeROI(nx, ny, nz, lx, ly, lz, CenterROI);

level = 0.0;  % Положение плоскости
plane = "XY";  % Выбор плоскости XY, XZ, YZ

if plane == "XY"
    disp(linspace(-lz/2, lz/2, nz)+CenterROI(3));
elseif plane == "XZ"
    disp(linspace(-ly/2, ly/2, ny)+CenterROI(2));
elseif plane == "YZ"
    disp(linspace(-lx/2, lx/2, nx)+CenterROI(1));
end


[XX, YY, BB] = PrintFieldCubeReturn(lx, ly, lz, nx, ny, nz, CenterROI, B(:,3)*10000, level, plane, lx, ly, lz, CenterROI, 'Полученное поле', 'Полученное поле, Гс'); % Отрисовка поля

figure(2)
surf(XX*1000, YY*1000, BB)
xlabel('x, мм'), ylabel('y, мм'), title(strcat('Поле',', z = ', num2str(level*1000), 'мм'))
colorbar
%axis('equal')
box("on")
grid("on") 
hold("off")

% ------------------------------------------------------------------- Аппроксимация

G = [-1:0.0001:1];
B0 = [-0.001:0.00001:0.001];

Bt = G(1)*YY+B0(1);
E = 100*(Bt-BB/10000)./max(max(Bt));
a = max(max(abs(E)));
G0 = G(1);
B00 = B0(1);

for i = B0
    for j = G
        Bt = j*YY+i;
        E = 100*(Bt-BB/10000)./max(max(Bt));
        if max(max(abs(E))) < a
            G0 = j;
            B00 = i;
            a = max(max(abs(E)));
        end
    end
end

disp(strcat('Градиент:', ' ', num2str(G0)))
disp(strcat('Фон:', ' ', num2str(B00)))
disp(strcat('Отклонение:', ' ',num2str(a),' %'))
Bt = G0*YY+B00;

figure(3)
surf(XX, YY, BB/10000)
hold on
surf(XX, YY, Bt)
xlabel('x, мм'), ylabel('y, мм'), title(strcat('Поле',', z = ', num2str(level*1000), 'мм'))
colorbar
%axis('equal')
box("on")
grid("on") 
hold("off")


E = 100*(Bt-BB/10000)./max(max(Bt));

figure(4)
contourf(XX*1000,YY*1000, E);
xlabel('x, мм'), ylabel('y, мм'), title(strcat('Разность, %',', z = ', num2str(level*1000), 'мм'))
colorbar
axis('equal')
box("on")
grid("on") 


